SELECT COUNT(*) FROM customers WHERE id NOT IN (SELECT rep_id FROM customers);
SELECT COUNT(*) FROM employees WHERE id NOT IN (SELECT manager_id FROM employees WHERE manager_id IS NOT NULL);
SELECT COUNT(*) FROM customers WHERE tier NOT IN (1, 2);
SELECT COUNT(*) FROM customers WHERE tier IN (1, NULL);
SELECT COUNT(*) FROM customers WHERE NOT (tier IN (1, NULL));
SELECT COUNT(*) FROM customers WHERE tier IN (SELECT tier FROM customers WHERE id < 0);
SELECT COUNT(*) FROM customers WHERE NULL IN (SELECT tier FROM customers WHERE id < 0);
SELECT COUNT(*) FROM customers WHERE tier = NULL;
SELECT COUNT(*) FROM customers WHERE tier <> 2;
SELECT COUNT(*) FROM customers WHERE NOT tier = 2;
SELECT COUNT(*) FROM customers WHERE tier = 2 OR tier IS NULL;
SELECT COUNT(*) FROM customers WHERE (tier > 2) IS NULL;
SELECT NULL AND 0, NULL AND 1, NULL OR 1, NULL OR 0, NOT NULL, 1 AND 2, 0 OR 0 FROM departments WHERE id = 1;
SELECT NULL = NULL, NULL IS NULL, 1 IS NOT NULL, NULL <> 1, 3 BETWEEN NULL AND 5, 3 BETWEEN 4 AND NULL FROM departments WHERE id = 1;
SELECT 1 IN (1, NULL), 2 IN (1, NULL), 2 NOT IN (1, NULL), NULL IN (1), 1 NOT IN (2, 3) FROM departments WHERE id = 1;
SELECT c.id, COUNT(o.id) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'paid' GROUP BY c.id ORDER BY COUNT(o.id) DESC, c.id LIMIT 10;
SELECT COUNT(*) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL;
SELECT COUNT(*) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'refunded' WHERE o.id IS NULL;
SELECT COUNT(*) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.status = 'refunded';
SELECT COUNT(*) FROM orders o LEFT JOIN customers c ON c.id = o.customer_id WHERE c.id IS NULL;
SELECT o.id, o.customer_id FROM orders o LEFT JOIN customers c ON c.id = o.customer_id WHERE c.id IS NULL AND o.customer_id IS NOT NULL ORDER BY o.id LIMIT 10;
SELECT COUNT(*), COUNT(r.id) FROM products p LEFT JOIN reviews r ON r.product_id = p.id;
SELECT p.id, COUNT(r.id), AVG(r.stars) FROM products p LEFT JOIN reviews r ON r.product_id = p.id GROUP BY p.id HAVING COUNT(r.id) = 0 ORDER BY p.id;
SELECT r.product_id, COUNT(*) FROM reviews r LEFT JOIN products p ON p.id = r.product_id WHERE p.id IS NULL GROUP BY r.product_id ORDER BY r.product_id;
SELECT e.id, m.id, mm.id FROM employees e LEFT JOIN employees m ON m.id = e.manager_id LEFT JOIN employees mm ON mm.id = m.manager_id ORDER BY e.id LIMIT 12;
SELECT COUNT(*) FROM employees e JOIN employees m ON e.manager_id = m.id WHERE e.salary > m.salary;
SELECT m.id, COUNT(*) AS reports, MAX(e.salary) FROM employees e JOIN employees m ON e.manager_id = m.id GROUP BY m.id HAVING COUNT(*) >= 6 ORDER BY reports DESC, m.id;
SELECT d.name, COUNT(e.id), SUM(e.salary), MIN(e.salary), MAX(e.salary) FROM departments d LEFT JOIN employees e ON e.dept_id = d.id GROUP BY d.id ORDER BY d.id;
SELECT COUNT(*) FROM employees WHERE dept_id IS NULL;
SELECT dept_id, COUNT(*) FROM employees GROUP BY dept_id ORDER BY dept_id;
SELECT tier, city, COUNT(*) FROM customers GROUP BY tier, city HAVING COUNT(*) > 18 ORDER BY tier, city;
SELECT city, COUNT(*) FROM customers GROUP BY city HAVING city LIKE 'h%' ORDER BY city;
SELECT city, AVG(tier), SUM(tier), COUNT(tier), TOTAL(tier) FROM customers GROUP BY city ORDER BY city;
SELECT COUNT(*), SUM(tier), AVG(tier), MIN(tier), MAX(tier), TOTAL(tier) FROM customers WHERE id > 10000;
SELECT COUNT(*) FROM (SELECT city FROM customers GROUP BY city) t;
SELECT category, COUNT(*), COUNT(stock), SUM(stock), MAX(price) - MIN(price) FROM products GROUP BY category ORDER BY category;
SELECT COUNT(DISTINCT tier), COUNT(DISTINCT city), COUNT(DISTINCT rep_id) FROM customers;
SELECT SUM(DISTINCT tier), AVG(DISTINCT tier), SUM(tier) FROM customers;
SELECT status, ROUND(AVG(discount), 4), COUNT(discount), COUNT(*) FROM orders GROUP BY status ORDER BY status;
SELECT status, SUM(CASE WHEN discount IS NULL THEN 1 ELSE 0 END), SUM(discount > 0) FROM orders GROUP BY status ORDER BY 1;
SELECT method, COUNT(*), ROUND(SUM(amount), 2) FROM payments GROUP BY method ORDER BY method;
SELECT COUNT(*) FROM payments WHERE amount < 0;
SELECT o.id, o.status, ROUND(SUM(p.amount), 2) FROM orders o JOIN payments p ON p.order_id = o.id GROUP BY o.id HAVING SUM(p.amount) > 1500 ORDER BY o.id;
SELECT COUNT(*) FROM orders o WHERE NOT EXISTS (SELECT 1 FROM payments p WHERE p.order_id = o.id);
SELECT COUNT(*) FROM orders o WHERE EXISTS (SELECT 1 FROM payments p WHERE p.order_id = o.id AND p.method IS NULL);
SELECT o.status, COUNT(*) FROM orders o WHERE (SELECT COUNT(*) FROM payments p WHERE p.order_id = o.id) >= 2 GROUP BY o.status ORDER BY o.status;
SELECT id, (SELECT MAX(stars) FROM reviews r WHERE r.product_id = p.id), (SELECT name FROM products q WHERE q.id = p.id + 1) FROM products p ORDER BY id LIMIT 8;
SELECT id, name FROM products p WHERE price > (SELECT AVG(price) FROM products q WHERE q.category = p.category) AND category = 'toy' ORDER BY id;
SELECT id FROM products p WHERE NOT EXISTS (SELECT 1 FROM order_items i WHERE i.product_id = p.id) ORDER BY id;
SELECT c.id, (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id) AS n, (SELECT MAX(day) FROM orders o WHERE o.customer_id = c.id) FROM customers c ORDER BY n DESC, c.id LIMIT 6;
SELECT id FROM customers c WHERE (SELECT COUNT(*) FROM orders o WHERE o.customer_id = c.id) = 0 ORDER BY id;
SELECT id, (SELECT id FROM orders o WHERE o.customer_id = c.id ORDER BY day DESC, id DESC LIMIT 1) FROM customers c ORDER BY id LIMIT 10;
SELECT (SELECT name FROM departments WHERE id = 99), (SELECT COUNT(*) FROM departments WHERE id = 99) FROM departments WHERE id = 1;
SELECT e.id FROM employees e WHERE e.salary = (SELECT MAX(salary) FROM employees x WHERE x.dept_id = e.dept_id) ORDER BY e.id;
SELECT d.id, (SELECT name FROM employees e WHERE e.dept_id = d.id ORDER BY salary DESC, id LIMIT 1) FROM departments d ORDER BY d.id;
SELECT id FROM employees e WHERE EXISTS (SELECT 1 FROM employees r WHERE r.manager_id = e.id AND EXISTS (SELECT 1 FROM employees rr WHERE rr.manager_id = r.id)) ORDER BY id;
SELECT COUNT(*) FROM order_items WHERE unit_price IS NULL;
SELECT i.order_id, i.product_id, i.qty * COALESCE(i.unit_price, p.price) FROM order_items i LEFT JOIN products p ON p.id = i.product_id WHERE i.unit_price IS NULL ORDER BY i.order_id, i.product_id;
SELECT o.id, ROUND(SUM(i.qty * i.unit_price) * (1 - COALESCE(o.discount, 0)), 2) AS net FROM orders o JOIN order_items i ON i.order_id = o.id WHERE o.status <> 'cancelled' GROUP BY o.id ORDER BY net DESC, o.id LIMIT 8;
SELECT o.id, SUM(i.qty * i.unit_price) FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.id HAVING SUM(i.qty * i.unit_price) IS NULL ORDER BY o.id LIMIT 10;
SELECT SUBSTR(day, 6, 2) AS m, COUNT(*), COUNT(DISTINCT customer_id) FROM orders GROUP BY m ORDER BY m;
SELECT SUBSTR(day, 6, 2) AS m, status, COUNT(*) FROM orders WHERE status IN ('paid', 'shipped') GROUP BY m, status ORDER BY m, status;
SELECT COUNT(*) FROM orders WHERE day BETWEEN '2025-03-01' AND '2025-03-31';
SELECT COUNT(*) FROM orders WHERE day >= '2025-12-01' OR day < '2025-01-15';
SELECT MIN(hired), MAX(hired), COUNT(*) FROM employees WHERE hired LIKE '2019%';
SELECT id, name FROM products WHERE name LIKE '%\_%' ORDER BY id LIMIT 5;
SELECT COUNT(*) FROM products WHERE name LIKE '%_%';
SELECT COUNT(*) FROM products WHERE name LIKE '%''%';
SELECT id, name FROM products WHERE name LIKE '%''s pick' ORDER BY id LIMIT 5;
SELECT COUNT(*) FROM products WHERE name LIKE '%50%%';
SELECT COUNT(*) FROM products WHERE name NOT LIKE 'book%';
SELECT COUNT(*) FROM products WHERE category NOT LIKE 'book';
SELECT COUNT(*) FROM reviews WHERE body LIKE '%great%';
SELECT COUNT(*) FROM reviews WHERE body LIKE 'GREAT%';
SELECT COUNT(*) FROM reviews WHERE body LIKE '%a_b%';
SELECT COUNT(*) FROM reviews WHERE body LIKE '%100%%';
SELECT COUNT(*) FROM reviews WHERE body LIKE '_';
SELECT COUNT(*) FROM reviews WHERE body LIKE '__';
SELECT COUNT(*) FROM reviews WHERE body LIKE '%';
SELECT stars, COUNT(*) FROM reviews GROUP BY stars ORDER BY stars DESC;
SELECT stars, COUNT(*) FROM reviews GROUP BY stars ORDER BY stars;
SELECT id, stars FROM reviews WHERE stars IS NOT NULL ORDER BY stars DESC, id DESC LIMIT 5 OFFSET 3;
SELECT id FROM reviews ORDER BY body, id LIMIT 7;
SELECT id FROM reviews ORDER BY body DESC, id LIMIT 7;
SELECT DISTINCT stars FROM reviews ORDER BY stars;
SELECT DISTINCT category, stock IS NULL FROM products ORDER BY 1, 2;
SELECT DISTINCT city FROM customers;
SELECT DISTINCT tier, city FROM customers WHERE tier = 4 ORDER BY city;
SELECT tier AS t, COUNT(*) AS n FROM customers GROUP BY tier ORDER BY n, t;
SELECT tier, COUNT(*) FROM customers GROUP BY 1 ORDER BY 2 DESC, 1;
SELECT name, salary FROM employees ORDER BY salary DESC, name, id LIMIT 5;
SELECT name, salary FROM employees ORDER BY 2, 1, id LIMIT 5;
SELECT id, price * stock AS value FROM products WHERE stock IS NOT NULL ORDER BY value DESC, id LIMIT 5;
SELECT id FROM products ORDER BY stock, id LIMIT 6;
SELECT id FROM products ORDER BY stock DESC, id LIMIT 6;
SELECT id FROM products ORDER BY -price, id LIMIT 4;
SELECT id FROM products ORDER BY id LIMIT 3 OFFSET 178;
SELECT id FROM products ORDER BY id LIMIT 0;
SELECT id FROM products ORDER BY id LIMIT 2 + 1;
SELECT 2 + 3 * 4, (2 + 3) * 4, 10 - 4 - 3, 2 * 3 % 4, 17 % 5 * 2, -3 * -3, 1 - -1 FROM departments WHERE id = 1;
SELECT 7 / 2, -7 / 2, 7 / -2, 7 % 3, -7 % 3, 7 % -3, 1 / 2 * 4, 1.0 / 2 * 4 FROM departments WHERE id = 1;
SELECT 10 / 0, 10 % 0, 10.0 / 0, NULL + 1, 2 * NULL, -NULL FROM departments WHERE id = 1;
SELECT 5 > 3 AND 2 > 1, 5 > 3 = 1, 1 + 1 = 2, 'a' || 'b' || 'c', 'x' || 1 || 2.5 FROM departments WHERE id = 1;
SELECT 3.0 || '', 2 || 3, LENGTH(12345), LENGTH(3.0), LENGTH(NULL), 'it''s' FROM departments WHERE id = 1;
SELECT ROUND(2.5), ROUND(-2.5), ROUND(3.14159, 3), ROUND(-0.4), ROUND(7) FROM departments WHERE id = 1;
SELECT ABS(-5), ABS(-2.5), ABS(NULL), CAST(7.9 AS INTEGER), CAST(-7.9 AS INTEGER), CAST(3 AS REAL), CAST(12 AS TEXT) || 'x' FROM departments WHERE id = 1;
SELECT SUBSTR('hello', 2), SUBSTR('hello', 2, 2), SUBSTR('hello', -3, 2), SUBSTR('hello', 0), SUBSTR('hello', 0, 1), SUBSTR('hello', 9), SUBSTR('hello', 5, 9) FROM departments WHERE id = 1;
SELECT UPPER('aBc1'), LOWER('ÁbC'), TRIM('  x y  '), REPLACE('aaa', 'a', 'bb'), INSTR('hello', 'l'), INSTR('hello', 'z'), INSTR('hello', '') FROM departments WHERE id = 1;
SELECT COALESCE(NULL, NULL, 3, 4), COALESCE(NULL, 'x'), NULLIF(3, 3), NULLIF(3, 4), IFNULL(NULL, 9), IFNULL(1, 9) FROM departments WHERE id = 1;
SELECT CASE WHEN NULL THEN 'a' ELSE 'b' END, CASE NULL WHEN NULL THEN 'a' ELSE 'b' END, CASE 2 WHEN 1 THEN 'x' WHEN 2 THEN 'y' END, CASE 3 WHEN 1 THEN 'x' END FROM departments WHERE id = 1;
SELECT id, CASE tier WHEN 1 THEN 'bronze' WHEN 2 THEN 'silver' WHEN 3 THEN 'gold' ELSE 'other' END FROM customers ORDER BY id LIMIT 12;
SELECT CASE WHEN stars >= 4 THEN 'good' WHEN stars <= 2 THEN 'bad' WHEN stars = 3 THEN 'ok' END AS k, COUNT(*) FROM reviews GROUP BY k ORDER BY k;
SELECT category, SUM(CASE WHEN stock = 0 THEN 1 ELSE 0 END), SUM(CASE WHEN stock IS NULL THEN 1 END) FROM products GROUP BY category ORDER BY category;
SELECT UPPER(SUBSTR(name, 1, 1)) || LOWER(SUBSTR(name, 2)) FROM departments ORDER BY id;
SELECT name, LENGTH(name) FROM products WHERE LENGTH(name) = (SELECT MAX(LENGTH(name)) FROM products) ORDER BY name;
SELECT COUNT(*) FROM departments d CROSS JOIN departments e WHERE d.id < e.id;
SELECT d.id, e.id FROM departments d JOIN departments e ON e.id = d.id + 1 ORDER BY d.id;
SELECT COUNT(*) FROM departments a, departments b, departments c WHERE a.id + b.id = c.id;
SELECT a.id, b.id FROM departments a JOIN departments b WHERE a.budget < b.budget AND b.id = 1 ORDER BY a.id;
SELECT * FROM departments d LEFT JOIN employees e ON e.dept_id = d.id AND e.salary > 8800 ORDER BY d.id, e.id;
SELECT d.*, 1 FROM departments d WHERE d.id <= 2 ORDER BY d.id;
SELECT t.n, COUNT(*) FROM (SELECT customer_id, COUNT(*) AS n FROM orders GROUP BY customer_id) t GROUP BY t.n ORDER BY t.n;
SELECT MAX(n), MIN(n), AVG(n) FROM (SELECT customer_id, COUNT(*) AS n FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id);
SELECT x.city, x.n FROM (SELECT city, COUNT(*) AS n FROM customers GROUP BY city) AS x WHERE x.n = (SELECT MAX(n) FROM (SELECT COUNT(*) AS n FROM customers GROUP BY city)) ORDER BY x.city;
WITH spend AS (SELECT o.customer_id AS cid, SUM(i.qty * i.unit_price) AS total FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id) SELECT c.city, ROUND(AVG(s.total), 2), COUNT(*) FROM spend s JOIN customers c ON c.id = s.cid GROUP BY c.city ORDER BY c.city;
WITH a AS (SELECT id, salary FROM employees WHERE dept_id = 1), b AS (SELECT id FROM a WHERE salary > (SELECT AVG(salary) FROM a)) SELECT COUNT(*), (SELECT COUNT(*) FROM a) FROM b;
WITH ranked AS (SELECT p.id, p.category, p.price FROM products p WHERE (SELECT COUNT(*) FROM products q WHERE q.category = p.category AND (q.price > p.price OR (q.price = p.price AND q.id < p.id))) < 2) SELECT category, id, price FROM ranked ORDER BY category, price DESC, id;
WITH c AS (SELECT city, tier FROM customers WHERE tier IS NOT NULL) SELECT city, COUNT(*) FROM c WHERE tier = 4 GROUP BY city UNION ALL SELECT 'all', COUNT(*) FROM c ORDER BY 1;
WITH x AS (SELECT 1 AS v UNION ALL SELECT 2 UNION ALL SELECT 2 UNION ALL SELECT NULL) SELECT COUNT(*), COUNT(v), COUNT(DISTINCT v), SUM(v) FROM x;
WITH top AS (SELECT customer_id FROM orders GROUP BY customer_id ORDER BY COUNT(*) DESC, customer_id LIMIT 5) SELECT c.id, c.name FROM customers c WHERE c.id IN (SELECT customer_id FROM top) ORDER BY c.id;
SELECT 1 UNION SELECT 1 UNION SELECT 2;
SELECT 1 UNION ALL SELECT 1 UNION SELECT 2;
SELECT 1 UNION SELECT 1 UNION ALL SELECT 1;
SELECT NULL UNION SELECT NULL UNION SELECT 3 ORDER BY 1;
SELECT city FROM customers WHERE tier = 1 UNION SELECT city FROM customers WHERE tier = 4 ORDER BY city;
SELECT id, 'd' FROM departments WHERE id < 3 UNION ALL SELECT id, 'e' FROM employees WHERE id < 3 ORDER BY 2 DESC, 1;
SELECT status AS s FROM orders UNION SELECT method FROM payments ORDER BY s;
SELECT COUNT(*) FROM (SELECT customer_id FROM orders UNION SELECT id FROM customers);
SELECT COUNT(*) FROM (SELECT product_id, customer_id FROM reviews UNION ALL SELECT product_id, customer_id FROM reviews);
SELECT tier, COUNT(*) FROM customers WHERE city = 'Hanoi' GROUP BY tier HAVING tier IS NOT NULL AND COUNT(*) > 5 ORDER BY tier;
SELECT category FROM products GROUP BY category HAVING MIN(price) < 2 OR MAX(price) > 399 ORDER BY category;
SELECT customer_id FROM orders GROUP BY customer_id HAVING SUM(status = 'cancelled') >= 3 ORDER BY customer_id;
SELECT customer_id, COUNT(*) FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id HAVING COUNT(*) = (SELECT MAX(n) FROM (SELECT COUNT(*) AS n FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id)) ORDER BY customer_id;
SELECT r.stars, ROUND(AVG(p.price), 2) FROM reviews r JOIN products p ON p.id = r.product_id WHERE r.stars IS NOT NULL GROUP BY r.stars ORDER BY r.stars;
SELECT p.category, COUNT(*) FROM reviews r JOIN products p ON p.id = r.product_id JOIN customers c ON c.id = r.customer_id WHERE c.city = 'Hue' AND r.stars = 5 GROUP BY p.category ORDER BY p.category;
SELECT c.id FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.id HAVING COUNT(DISTINCT p.category) = 6 ORDER BY c.id;
SELECT e.name, d.name FROM employees e JOIN departments d ON d.id = e.dept_id WHERE e.manager_id IN (SELECT id FROM employees WHERE dept_id = d.id) ORDER BY e.id LIMIT 10;
SELECT COUNT(*) FROM customers c WHERE c.rep_id IN (SELECT e.id FROM employees e JOIN departments d ON d.id = e.dept_id WHERE d.name = 'Sales');
SELECT d.name, COUNT(c.id) FROM departments d LEFT JOIN employees e ON e.dept_id = d.id LEFT JOIN customers c ON c.rep_id = e.id GROUP BY d.id ORDER BY d.id;
SELECT COUNT(*) FROM customers WHERE rep_id NOT IN (SELECT id FROM employees);
SELECT COUNT(*) FROM customers c WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.id = c.rep_id);
SELECT id, name FROM customers WHERE name LIKE '% an' ORDER BY id LIMIT 6;
SELECT COUNT(*) FROM customers WHERE LOWER(name) = LOWER('NGUYEN AN');
SELECT COUNT(*) FROM customers WHERE name = 'nguyen an';
SELECT name, COUNT(*) FROM customers GROUP BY name HAVING COUNT(*) >= 6 ORDER BY COUNT(*) DESC, name;
SELECT id FROM orders WHERE discount > 0.1 OR discount IS NULL AND status = 'paid' ORDER BY id LIMIT 8;
SELECT id FROM orders WHERE (discount > 0.1 OR discount IS NULL) AND status = 'paid' ORDER BY id LIMIT 8;
SELECT id FROM orders WHERE NOT discount > 0 AND NOT status = 'new' ORDER BY id LIMIT 8;
SELECT COUNT(*) FROM orders WHERE NOT (discount > 0 OR status = 'new');
SELECT COUNT(*) FROM orders WHERE discount NOT BETWEEN 0.01 AND 0.2;
SELECT COUNT(*) FROM orders WHERE discount BETWEEN 0.05 AND 0.1;
SELECT ROUND(SUM(amount) / COUNT(*), 6), ROUND(AVG(amount), 6) FROM payments WHERE method = 'cash';
SELECT COUNT(*) / 7, COUNT(*) % 7, COUNT(*) * 1.0 / 7 FROM orders;
SELECT id, stock / 7, stock % 7, -stock / 7 FROM products WHERE stock IS NOT NULL ORDER BY id LIMIT 6;
SELECT id, ROUND(price / 3, 4), price * 2 FROM products ORDER BY id LIMIT 5;
